import {matchSession} from './match-session.js';
import {PITCHSIDE} from './pitchside-story.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;};
export function createBroadcastOutput(){
 let room=null,base='',busy=false,stopped=false,failures=0,timer;
 const config=fetch('api-config.json').then(r=>r.json()).then(c=>base=['localhost','127.0.0.1'].includes(location.hostname)?'':c.baseUrl||'');
 const dialog=el('dialog','sheet overlay-dialog'),close=el('button','close-sheet','×'),status=el('p','output-status'),start=el('button','red-button','Start live output'),stop=el('button','outline-button','Stop output'),copy=el('button','outline-button','Copy renderer link'),link=el('a','overlay-link','Open transparent output ↗'),frame=el('iframe','overlay-frame'),actions=el('div','output-actions');
 dialog.setAttribute('aria-label','Live broadcast output');close.setAttribute('aria-label','Close output');close.onclick=()=>dialog.close();frame.title='Live broadcast cue preview';link.target='_blank';link.rel='noopener';link.hidden=copy.hidden=stop.hidden=frame.hidden=true;
 actions.append(start,copy,stop);dialog.append(close,el('span','eyebrow','BTR / LIVE GRAPHICS'),el('h2','','One story. Any screen.'),el('p','','Open the read-only link in another browser or an OBS browser source. It follows your source, playhead, language and perspective through Azure. Keep this producer tab open.'),actions,status,link,frame,el('p','sheet-note','Links last 30 minutes. Cues clear after six seconds without an update. Server restarts end the room. This is a working browser output; a rendering partner is not connected.'));document.body.append(dialog);
 const input=()=>{const s=matchSession.get();return {...s,clip_id:PITCHSIDE.id,time:s.source==='pitchside'?s.clipTime:s.time};};
 async function call(path,body,key){const r=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json',...(key?{Authorization:'Bearer '+key}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(8000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Output unavailable');return data;}
 async function update(){if(!room||busy||stopped)return;busy=true;try{await call(`/api/broadcast/${room.id}/update`,input(),room.writeKey);failures=0;status.textContent='LIVE · following '+(input().source==='pitchside'?'the film':'the synthetic match')+' · link expires '+new Date(room.expires_at).toLocaleTimeString();}catch(e){status.textContent=e.message+' · stale cues clear automatically.';if(++failures>=3){clearInterval(timer);stopped=true;start.hidden=false;start.textContent='Reconnect output';}}finally{busy=false;}}
 start.onclick=async()=>{start.disabled=true;try{await config;if(room&&!stopped)await call(`/api/broadcast/${room.id}/stop`,{},room.writeKey);room=await call('/api/broadcast',input());stopped=false;failures=0;const url=new URL('overlay.html',location.href);url.hash=new URLSearchParams({room:room.id,key:room.readKey}).toString();link.href=url.href;frame.src=url.href;link.hidden=copy.hidden=stop.hidden=frame.hidden=false;start.hidden=true;clearInterval(timer);timer=setInterval(update,1000);await update();}catch(e){status.textContent=e.message;}finally{start.disabled=false;}};
 stop.onclick=async()=>{clearInterval(timer);stopped=true;try{if(room)await call(`/api/broadcast/${room.id}/stop`,{},room.writeKey);status.textContent='Output stopped. The renderer is clear.';}catch{status.textContent='Producer stopped. The last cue clears within six seconds.';}start.hidden=false;start.textContent='Start new output';stop.hidden=true;};
 copy.onclick=async()=>{try{await navigator.clipboard.writeText(link.href);copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy renderer link',1800);}catch{status.textContent='Open the output link and copy its address.';}};
 window.addEventListener('pagehide',()=>{clearInterval(timer);if(room)fetch(base+`/api/broadcast/${room.id}/stop`,{method:'POST',headers:{Authorization:'Bearer '+room.writeKey},keepalive:true}).catch(()=>{});});
 return ()=>dialog.showModal();
}
